function updateHeaderIcons(tableKey,field,asc){const tableMap={'team-roster':'team-roster-table','events':'events-table','teams':'teams-table','players-dir':'players-table','factions':'faction-meta-table','player-matches':'player-matches-table','event-results':'event-results-table','event-elo':'event-elo-table','event-pairings':'event-pairings-table',};const tableId=tableMap[tableKey];if(!tableId)return;const tbl=document.getElementById(tableId);if(!tbl)return;tbl.querySelectorAll('th.sortable').forEach(th=>{th.classList.remove('sorted-asc','sorted-desc');const onclick=th.getAttribute('onclick')||'';if(onclick.includes(`'${field}'`)||onclick.includes(`"${field}"`)){th.classList.add(asc?'sorted-asc':'sorted-desc');}});}
function renderPaginationBar(containerId,pagination,onPageChange,onPageSizeChange){const container=document.getElementById(containerId);if(!container)return;const total=pagination.total||0;const page=pagination.page||1;const pageSize=pagination.pageSize||25;const totalPages=pagination.totalPages||Math.max(1,Math.ceil(total/pageSize));if(total===0){container.innerHTML='';return;}
const startItem=(page-1)*pageSize+1;const endItem=Math.min(total,page*pageSize);let pages=[];const maxButtons=5;let startPage=Math.max(1,page-Math.floor(maxButtons/2));let endPage=Math.min(totalPages,startPage+maxButtons-1);if(endPage-startPage+1<maxButtons){startPage=Math.max(1,endPage-maxButtons+1);}
for(let p=startPage;p<=endPage;p++){pages.push(p);}
let html=`
    <div class="pagination-info">
      Showing <b>${startItem.toLocaleString()}</b>–<b>${endItem.toLocaleString()}</b> of <b>${total.toLocaleString()}</b>
      <div class="page-size-selector" style="margin-left: 0.5rem;">
        <span>Rows:</span>
        <select class="page-size-select" onchange="${onPageSizeChange}(Number(this.value))">
          <option value="25" ${pageSize === 25 ? 'selected' : ''}>25</option>
          <option value="50" ${pageSize === 50 ? 'selected' : ''}>50</option>
          <option value="100" ${pageSize === 100 ? 'selected' : ''}>100</option>
        </select>
      </div>
    </div>
    <div class="pagination-controls">
      <button class="pagination-btn" ${page <= 1 ? 'disabled' : ''} onclick="${onPageChange}(1)" title="First Page">«</button>
      <button class="pagination-btn" ${page <= 1 ? 'disabled' : ''} onclick="${onPageChange}(${page - 1})" title="Previous Page">‹ Prev</button>
  `;if(startPage>1){html+=`<button class="pagination-btn" onclick="${onPageChange}(1)">1</button>`;if(startPage>2)html+=`<span style="color:var(--text-muted); padding:0 0.2rem;">…</span>`;}
pages.forEach(p=>{html+=`<button class="pagination-btn ${p === page ? 'active' : ''}" onclick="${onPageChange}(${p})">${p}</button>`;});if(endPage<totalPages){if(endPage<totalPages-1)html+=`<span style="color:var(--text-muted); padding:0 0.2rem;">…</span>`;html+=`<button class="pagination-btn" onclick="${onPageChange}(${totalPages})">${totalPages}</button>`;}
html+=`
      <button class="pagination-btn" ${page >= totalPages ? 'disabled' : ''} onclick="${onPageChange}(${page + 1})" title="Next Page">Next ›</button>
      <button class="pagination-btn" ${page >= totalPages ? 'disabled' : ''} onclick="${onPageChange}(${totalPages})" title="Last Page">»</button>
    </div>
  `;container.innerHTML=html;}
