if(!formatted&&typeof window!=='undefined'&&typeof window.api?.reverseGeocode==='function'){try{const rev=await window.api.reverseGeocode(numLat,numLng);if(rev&&rev.formatted&&!rev.formatted.startsWith('GPS (')){formatted=rev.formatted;resolvedCity=rev.city||(rev.formatted.split(',')[0]?.trim())||'';resolvedState=rev.state||(rev.formatted.split(',')[1]?.trim())||'';resolvedCountry=rev.country||'United States';}}catch(e){console.warn('Backend reverse-geocode notice:',e);}}
