function renderTrajectoryChart(trajectory){const svg=document.getElementById('trajectory-svg');if(!svg||!trajectory||trajectory.length===0)return;const w=svg.clientWidth||760;const h=200;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML='';const elos=trajectory.map(t=>Number(t.elo));const minElo=Math.floor(Math.min(...elos)-20);const maxElo=Math.ceil(Math.max(...elos)+20);const range=maxElo-minElo||1;const padX=40;const padY=25;const plotW=w-padX*2;const plotH=h-padY*2;const points=trajectory.map((t,idx)=>{const x=padX+(idx/(trajectory.length-1||1))*plotW;const y=padY+plotH-((Number(t.elo)-minElo)/range)*plotH;return{x,y,elo:Number(t.elo),result:t.result,date:t.date};});const gridLines=4;for(let i=0;i<=gridLines;i++){const val=minElo+(range/gridLines)*i;const y=padY+plotH-(i/gridLines)*plotH;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',padX);line.setAttribute('y1',y);line.setAttribute('x2',w-padX);line.setAttribute('y2',y);line.setAttribute('stroke','#1e2533');line.setAttribute('stroke-dasharray','3,3');svg.appendChild(line);const txt=document.createElementNS('http://www.w3.org/2000/svg','text');txt.setAttribute('x',padX-8);txt.setAttribute('y',y+4);txt.setAttribute('fill','#64748b');txt.setAttribute('font-size','10');txt.setAttribute('font-family','monospace');txt.setAttribute('text-anchor','end');txt.textContent=Math.round(val);svg.appendChild(txt);}
let dStr=`M ${points[0].x} ${points[0].y}`;for(let i=1;i<points.length;i++){dStr+=` L ${points[i].x} ${points[i].y}`;}
const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',dStr);path.setAttribute('fill','none');path.setAttribute('stroke','#38bdf8');path.setAttribute('stroke-width','2.5');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');svg.appendChild(path);points.forEach(pt=>{const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('cx',pt.x);circle.setAttribute('cy',pt.y);circle.setAttribute('r','4');circle.setAttribute('fill',pt.result==='W'?'#22c55e':(pt.result==='L'?'#ef4444':'#eab308'));circle.setAttribute('stroke','#0a0c10');circle.setAttribute('stroke-width','1.5');svg.appendChild(circle);});}
