let loginOpt=document.getElementById('mobile-opt-login');let feedbackOpt=document.getElementById('mobile-opt-feedback');let settingsOpt=document.getElementById('mobile-opt-settings');let logoutOpt=document.getElementById('mobile-opt-logout');if(currentUser){if(loginOpt)loginOpt.remove();if(!feedbackOpt){feedbackOpt=document.createElement('option');feedbackOpt.value='feedback';feedbackOpt.id='mobile-opt-feedback';feedbackOpt.textContent='💬 Send Feedback';select.appendChild(feedbackOpt);}
if(!settingsOpt){settingsOpt=document.createElement('option');settingsOpt.value='settings';settingsOpt.id='mobile-opt-settings';settingsOpt.textContent='⚙️ Account Settings';select.appendChild(settingsOpt);}
if(!logoutOpt){logoutOpt=document.createElement('option');logoutOpt.value='logout';logoutOpt.id='mobile-opt-logout';logoutOpt.textContent='🚪 Sign Out';select.appendChild(logoutOpt);}}else{if(feedbackOpt)feedbackOpt.remove();if(settingsOpt)settingsOpt.remove();if(logoutOpt)logoutOpt.remove();if(!loginOpt){loginOpt=document.createElement('option');loginOpt.value='login';loginOpt.id='mobile-opt-login';loginOpt.textContent='🔑 Sign In';select.appendChild(loginOpt);}}
