async function initAuth(){const token=localStorage.getItem('native_session_token')||localStorage.getItem('elo_auth_token')||getCookieToken();if(!token){currentUser=null;syncAppAuthView();return;}
try{const res=await window.api.getAuthMe(token);if(res&&res.authenticated&&res.user){currentUser=res.user;localStorage.setItem('native_user_profile',JSON.stringify(currentUser));localStorage.setItem('native_session_token',token);localStorage.setItem('elo_auth_token',token);if(typeof updateStudioAuthBadge==='function')updateStudioAuthBadge();}else{currentUser=null;localStorage.removeItem('native_session_token');localStorage.removeItem('elo_auth_token');localStorage.removeItem('native_user_profile');if(typeof updateStudioAuthBadge==='function')updateStudioAuthBadge();}}catch(e){console.warn('Session verification error:',e);}
syncAppAuthView();}
