const avgElo=ev.avg_elo_display?Math.round(ev.avg_elo_display):(ev.avg_field_elo?Math.round(ev.avg_field_elo):1550);const myElo=(typeof currentUser!=='undefined'&&(currentUser?.current_elo||currentUser?.elo))||(typeof myHubData!=='undefined'&&(myHubData?.player?.current_elo||myHubData?.player?.elo))||(typeof connectState!=='undefined'&&(connectState.userProfile?.current_elo||connectState.userProfile?.elo))||ev.user_elo||null;let deltaLabel='';let deltaBadge='badge-match-prime';if(myElo){const delta=avgElo-Math.round(myElo);const sign=delta>0?`+${delta}`:(delta<0?`${delta}`:`±0`);deltaLabel=`${sign} vs My Elo`;if(delta>75){deltaBadge='badge-match-extreme';}else if(delta>25){deltaBadge='badge-match-hard';}else if(delta<-25){deltaBadge='badge-match-favorable';}else{deltaBadge='badge-match-prime';}}else if(ev.skill_match_label&&!ev.skill_match_label.includes('Field Avg')){deltaLabel=ev.skill_match_label;deltaBadge=ev.skill_match_badge||'badge-match-prime';}else{deltaLabel='⚔️ Open Field';deltaBadge='badge-match-prime';}
