function handleStudioLocationKeydown(e){const dropdown=document.getElementById("create-event-loc-dropdown");if(!dropdown||dropdown.style.display==="none")return;if(e.key==="ArrowDown"){e.preventDefault();if(studioLocCurrentMatches.length===0)return;studioLocHighlightedIdx=(studioLocHighlightedIdx+1)%studioLocCurrentMatches.length;updateStudioDropdownHighlight();}else if(e.key==="ArrowUp"){e.preventDefault();if(studioLocCurrentMatches.length===0)return;studioLocHighlightedIdx=(studioLocHighlightedIdx-1+studioLocCurrentMatches.length)%studioLocCurrentMatches.length;updateStudioDropdownHighlight();}else if(e.key==="Enter"){e.preventDefault();if(studioLocCurrentMatches.length>0){const idx=studioLocHighlightedIdx>=0?studioLocHighlightedIdx:0;selectStudioLocationByIndex(idx);}}else if(e.key==="Escape"){dropdown.style.display="none";}}
