document.querySelectorAll('#comm-subview-tournaments .comm-filter-chip').forEach(c=>{c.classList.toggle('active',c.dataset.filter===(communityState.eventsFilter||'all'));});if(communityState.eventsFilter==='upcoming'){displayedRecent=[];}else if(communityState.eventsFilter==='recent'){displayedUpcoming=[];}
