function isValidStoreResult(name,types=[]){if(!name||name.trim().length<3)return false;const norm=name.trim().toLowerCase().replace(/['"]/g,'');const JUNK=['asdf','test','tbd','n/a','na','online','discord','unknown','somewhere'];if(JUNK.includes(norm))return false;const excludedTypes=['lodging','hotel','campground','tourist_attraction','airport','movie_theater','bar'];if(types&&Array.isArray(types)&&types.some(t=>excludedTypes.includes(t)))return false;const NON_STORES=['hotel','motel','resort','fairground','convention center','expo center','brewery','brewing','brewhouse','pub','tavern','winery','church'];if(NON_STORES.some(ns=>norm.includes(ns))){if(!norm.includes('board game')&&!norm.includes('tabletop cafe')&&!norm.includes('game cafe')){return false;}}
return true;}
