function updateStoresBadgesAndCounts(){const stores=communityState.stores||[];const total=stores.length;const tournamentsCount=stores.filter(s=>s.is_tournament_venue).length;const officialCount=stores.filter(s=>s.is_official_warhammer).length;const topCount=stores.filter(s=>s.rating&&s.rating>=4.5).length;const countBadge=document.getElementById('badge-stores-count');if(countBadge){countBadge.textContent=total;countBadge.style.display=total>0?'inline-block':'none';}
const elAll=document.getElementById('count-stores-all');if(elAll)elAll.textContent=total;const elTourneys=document.getElementById('count-stores-tournaments');if(elTourneys)elTourneys.textContent=tournamentsCount;const elOfficial=document.getElementById('count-stores-official');if(elOfficial)elOfficial.textContent=officialCount;const elTop=document.getElementById('count-stores-top');if(elTop)elTop.textContent=topCount;}
