async function loadGlobalStats(){try{const stats=await window.api.getStats();const elP=document.getElementById('stat-total-players');if(elP)elP.innerText=formatNumber(stats.total_players||0);const elM=document.getElementById('stat-total-matches');if(elM)elM.innerText=formatNumber(stats.total_matches||0);const elE=document.getElementById('stat-total-events');if(elE)elE.innerText=formatNumber(stats.total_events||0);const elTop=document.getElementById('stat-top-player');if(elTop)elTop.innerText=stats.top_player_name||'-';const elTopElo=document.getElementById('stat-top-elo');if(elTopElo)elTopElo.innerText=stats.top_player_elo?Number(stats.top_player_elo).toFixed(1):'-';const dirFactionSelect=document.getElementById('dir-faction-filter');if(stats.factions&&stats.factions.length>0){const flatFactions=Array.from(new Set(stats.factions.flatMap(f=>(typeof f==='string'?f.split(','):[f])).map(f=>f.trim()).filter(f=>f&&f!=='Unknown'&&f!=='Unknown Faction'))).sort();if(dirFactionSelect){dirFactionSelect.innerHTML='<option value="All">All Factions</option>';flatFactions.forEach(f=>{const opt=document.createElement('option');opt.value=f;opt.innerText=f;dirFactionSelect.appendChild(opt);});}}}catch(err){console.error('Failed to load summary stats:',err);}}
